CREATE OR REPLACE FUNCTION public.create_yorisou_candidate_offering(p_organization_id uuid, p_offering_type text, p_title text, p_summary text, p_external_url text, p_external_ref text, p_version_label text, p_supersedes_offering_id uuid, p_actor text, p_actor_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.yorisou_candidate_offerings;
begin
  insert into public.yorisou_candidate_offerings (
    organization_id, offering_type, title, summary, external_url, external_ref,
    version_label, supersedes_offering_id, created_by, created_by_type
  ) values (
    p_organization_id, p_offering_type, p_title, p_summary, p_external_url, p_external_ref,
    p_version_label, p_supersedes_offering_id, p_actor, coalesce(p_actor_type, 'admin')
  ) returning * into v_row;

  insert into public.yorisou_candidate_events (project_id, organization_id, offering_id, event_type, actor, actor_type, new_state)
    values ('yorisou', v_row.organization_id, v_row.id, 'created', p_actor, coalesce(p_actor_type, 'admin'), 'active');

  return to_jsonb(v_row);
end $function$

CREATE OR REPLACE FUNCTION public.record_yorisou_experience_interaction(p_experience_id uuid, p_actor_account_id text, p_action text, p_idempotency_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_actor_account_id !~ '^[A-Za-z0-9._:-]{1,200}$' or p_action not in ('save','try','tried','helpful','not_relevant') or char_length(p_idempotency_key) not between 16 and 200 then raise exception 'invalid interaction input'; end if;
  if (select count(*) from public.yorisou_experience_interactions where actor_account_id=p_actor_account_id and created_at>now()-interval '1 hour') >= 60 then raise exception 'interaction rate limited'; end if;
  insert into public.yorisou_experience_interactions(project_id,experience_id,actor_account_id,action,idempotency_key) values('yorisou',p_experience_id,p_actor_account_id,p_action,p_idempotency_key) on conflict(actor_account_id,idempotency_key) do update set idempotency_key=excluded.idempotency_key returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.set_yorisou_test_result_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
